baseline_sql:
SELECT client_id, MAX(investment) AS max_daily_investment
FROM daily_investments
GROUP BY client_id;

SELECT strategy_name, AVG(account_balance) AS avg_balance
FROM customers
GROUP BY strategy_name;

SELECT AVG(amount) AS avg_loan_amount
FROM loans
WHERE country IN ('Turkey', 'Iran');

SELECT AVG(value) AS average_value
FROM shariah_investments
WHERE country = 'United States';

SELECT c.name FROM customers c
JOIN transactions t ON c.id = t.customer_id
WHERE t.amount > 500 AND c.category = 'risk_management';

SELECT AVG(amount) AS average_investment
FROM investments
WHERE sector = 'Sustainable Agriculture';

SELECT AVG(financial_wellbeing_score) 
FROM shariah_compliant_customers 
WHERE wellbeing_assessment_date BETWEEN '2022-04-01' AND '2022-06-30';

SELECT MAX(amount_invested) FROM shariah_compliant_funds_investments WHERE client_id IN (
    SELECT client_id FROM clients WHERE client_name = 'Shariah Compliant'
);

SELECT SUM(CASE WHEN department = 'Department A' THEN 1 ELSE 0 END) + 
       SUM(CASE WHEN department = 'Department B' THEN 1 ELSE 0 END) AS total_policies
FROM policies;

SELECT MAX(amount) FROM transactions WHERE client_id IN (
    SELECT client_id FROM clients WHERE region = 'Americas'
);

SELECT organization_name, SUM(value) as total_value
FROM social_impact_bonds
GROUP BY organization_name;

SELECT COUNT(*) 
FROM transactions 
WHERE region = 'EMEA' AND transaction_date >= date('now', '-3 months');

SELECT region, COUNT(*) AS transaction_count
FROM transactions
GROUP BY region;

SELECT MAX(account_balance) FROM shariah_compliant_finance WHERE customer_id NOT IN (
    SELECT customer_id FROM shariah_compliant_finance ORDER BY account_balance DESC LIMIT 3
);

SELECT region, AVG(assets_value) AS avg_assets_value
FROM customers
GROUP BY region;

SELECT AVG(Amount) AS AverageAmount
FROM Investments
WHERE Country = 'SpecificCountry';

SELECT SUM(value) FROM sustainable_investments WHERE venture_capital_id IN (
    SELECT id FROM venture_capitals WHERE location = 'United States'
);

SELECT MAX(funding_round) FROM investment_rounds WHERE company_id IN (
    SELECT id FROM company WHERE industry = 'Healthtech' AND founder_gender = 'Female'
);

SELECT SUM(income) AS total_income, SUM(expenses) AS total_expenses
FROM FinancialWellbeingPrograms
WHERE country = 'Australia';

SELECT TransactionType, SUM(Amount) AS TotalAmount
FROM Transactions
GROUP BY TransactionType;

SELECT PolicyState, COUNT(*) AS TotalPolicies
FROM Policies
GROUP BY PolicyState;

SELECT MIN(Age) AS MinAge, MAX(Age) AS MaxAge
FROM Policyholders
WHERE Premium BETWEEN 1500 AND 5000;

SELECT gender, SUM(claim_amount) AS total_claim_amount
FROM claims
GROUP BY gender;
